### 2. Runtime Metrics Collection (GameRuntimeServer.ts)

Add metrics collection to existing GameRuntimeServer class:

```typescript
// Add to GameRuntimeServer class
private collectMetrics(): void {
  if (this.phase !== "running") return;

  const agentMetrics: Record<string, {
    agentId: string;
    actionsApplied: number;
    turnsCompleted: number;
    invalidOutputs: number;
    backoffTime: number;
  }> = {};

  // Collect agent-level metrics
  for (const [agentId, queue] of this.actionQueueByAgent.entries()) {
    const agentState = this.metrics.getAgentState(agentId);
    if (agentState) {
      agentMetrics[agentId] = {
        agentId,
        actionsApplied: agentState.actionsApplied,
        turnsCompleted: agentState.turnsCompleted,
        invalidOutputs: agentState.invalidOutputs,
        backoffTime: agentState.backoffUntil ? Math.max(0, agentState.backoffUntil - Date.now()) : 0
      };
    }
  }

  // Create metrics snapshot
  const metricsSnapshot = {
    version: "1.0.0",
    timestamp: Date.now(),
    metrics: {
      actionCount: this.metrics.getTotalActions(),
      turnCount: this.metrics.getTurnCount(),
      queueDepth: this.metrics.getQueueDepth(),
      agentMetrics: Object.values(agentMetrics)
    }
  };

  // Send to all clients
  this.emitMessage({
    version: PROTOCOL_VERSION,
    type: "metrics.snapshot",
    payload: metricsSnapshot
  });
}

// Add to MetricsTracker.ts (new file)
export class MetricsTracker {
  private totalActions = 0;
  private turnCount = 0;
  private agentStates = new Map<string, {
    actionsApplied: number;
    turnsCompleted: number;
    invalidOutputs: number;
    backoffUntil: number;
  }>();

  onActionApplied() {
    this.totalActions++;
    const agentId = /* get current agent from context */;
    const state = this.agentStates.get(agentId) || { actionsApplied: 0, turnsCompleted: 0, invalidOutputs: 0, backoffUntil: 0 };
    this.agentStates.set(agentId, { ...state, actionsApplied: state.actionsApplied + 1 });
  }

  onTurnCompleted() {
    this.turnCount++;
  }

  getTotalActions(): number {
    return this.totalActions;
  }

  getTurnCount(): number {
    return this.turnCount;
  }

  getQueueDepth(): number {
    return this.totalActions - (this.turnCount * 10); // Example calculation
  }

  getAgentState(agentId: string): {
    actionsApplied: number;
    turnsCompleted: number;
    invalidOutputs: number;
    backoffUntil: number;
  } | undefined {
    return this.agentStates.get(agentId);
  }

  snapshot(): {
    totalActions: number;
    turnCount: number;
    agentStates: Record<string, any>;
  } {
    return {
      totalActions: this.totalActions,
      turnCount: this.turnCount,
      agentStates: Object.fromEntries(this.agentStates)
    };
  }
}
```

